const stages = ['Before you start','Planning','Contractors','Materials','Before work','During works','Furnishing','Handover','Optional décor'];
const starter = [
  ['Inspect every room when collecting keys','Before you start','Must do','Check for visible defects and keep a record.'],
  ['Photograph defects clearly','Before you start','Must do','Keep wide and close-up photos for your records.'],
  ['Set your renovation budget','Planning','Must do','Include a reserve for unexpected costs.'],
  ['Define the scope for each room','Planning','Helpful','Write down your priorities and measurements.'],
  ['Compare contractor quotations','Contractors','Must do','Review inclusions, exclusions and payment terms.'],
  ['Agree written work scope and payment stages','Contractors','Must do','Keep a copy of the agreed terms.'],
  ['Choose materials and finishes','Materials','Helpful','Compare samples and confirm lead times.'],
  ['Confirm approvals before work begins','Before work','Must do','Check applicable requirements with the relevant parties.'],
  ['Review work progress with contractors','During works','Helpful','Record decisions and changes along the way.'],
  ['Arrange furnishings and appliances','Furnishing','Helpful','Check measurements and delivery dates.'],
  ['Inspect completed work and record defects','Handover','Must do','List outstanding work before closing out.'],
  ['Plan finishing touches','Optional décor','Optional','Choose the details that make the space yours.']
];
const uid = () => crypto.randomUUID();
const initial = () => ({version:1,project:{name:'Your renovation',type:'',location:'',currency:'MYR',target:0,reserve:0,savings:0,savingsDate:'',moveIn:''},costs:[],payments:[],quotes:[],tasks:starter.map(([title,stage,importance,description])=>({id:uid(),title,stage,importance,description,status:'Not started',room:'',due:''}))});
const cloud=window.renovationCloud||null;
let state, loadError = '';
try { const raw=cloud?null:localStorage.getItem(KEY); state=withNewSections(cloud?(cloud.initialProject||initial()):(raw ? JSON.parse(raw) : initial())); if (!state.project || !Array.isArray(state.costs) || !Array.isArray(state.payments) || !Array.isArray(state.quotes) || !Array.isArray(state.tasks) || !validNewSections(state)) throw Error('Invalid data'); } catch { state=withNewSections(initial()); loadError='Your saved data could not be read. It has not been overwritten. Restore a backup or contact support before making changes.'; }
let lastSaved=JSON.stringify(state);
let page='home', filterText='', filterStatus='All', categoryMode='agreed';
let phaseFilter='all', categoryFilter='', areaFilter='', paidFilter='all';
let budgetSort={key:'',direction:'asc'}, paymentSort={key:'date',direction:'desc'};
let inlineEdit=null;
const app=document.querySelector('#app'), dialog=document.querySelector('#dialog'), dialogContent=document.querySelector('#dialog-content');
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = n => new Intl.NumberFormat('en-MY',{style:'currency',currency:state.project.currency||'MYR',maximumFractionDigits:2,minimumFractionDigits:0}).format((n||0)/100).replace('MYR','RM');
const amountValue = n => ((n || 0)/100).toFixed(2);
const selected = (a,b) => a===b?' selected':'';
const options = (items, value) => items.map(x=>`<option${selected(x,value)}>${esc(x)}</option>`).join('');
function save() {
  if (loadError) { alert(loadError); return false; }
  try { const serialized=JSON.stringify(state); if(cloud)cloud.session.stage(state);else localStorage.setItem(KEY, serialized); lastSaved=serialized; return true; }
  catch (error) { state=JSON.parse(lastSaved); alert(cloud?`Unable to queue the change for cloud sync: ${error.message}. Your change was not saved.`:'Unable to save in this browser. Your changes were not saved. Export a backup or free browser storage.'); return false; }
}
function notify(message){ const el=document.querySelector('#toast'); el.textContent=message; el.classList.add('show'); clearTimeout(notify.timer); notify.timer=setTimeout(()=>el.classList.remove('show'),2600); }
function commit(message='Saved on this device') { if(save()){ render(); notify(cloud?'Saving to cloud…':message); return true; } render(); return false; }
const cloudLabel=status=>status?.state==='error'&&/^\d{3}$/.test(status.detail||'')?`Sync failed (HTTP ${status.detail}) · retry or export backup`:({loading:'Opening cloud project',ready:'Cloud ready',saving:'Saving to cloud…',saved:'Saved to cloud',offline:'Offline · changes not synced',conflict:'Conflict · export backup and reload',error:'Sync failed · retry or export backup'})[status?.state]||'Cloud status unavailable';
function heading(kicker,title,sub,action=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p class="muted">${sub}</p></div>${action}</div>`;}
const nav=[['home','⌂','Home'],['checklist','☑','Checklist'],['budget','▤','Budget'],['quotes','⇄','Quotations'],['appliances','▧','Appliances'],['receipts','▣','Receipts'],['myhome','⚙','My home'],['guide','✧','Guide'],['seller','♧','Seller codes'],['more','☰','More']];
const mobileNav=nav.filter(([id])=>['home','checklist','budget','quotes','more'].includes(id));
function navButton([id,icon,label],active=page===id){return `<button class="${active?'active':''}" data-nav="${id}"${active?' aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${icon}</span>${label}</button>`;}
function render(){
  const title=esc(state.project.name);
  app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-icon">⌂</div><span>RENOVATION<br>COMPANION</span></div><nav class="nav" aria-label="Main navigation">${nav.map(item=>navButton(item)).join('')}</nav><div class="sidebar-note small"><strong>Need help?</strong><br>Start with your home details, then follow your checklist.<br><button class="button text" data-nav="guide">Open easy guide →</button></div></aside><main class="main"><header class="topbar"><span>${title}</span><div class="top-right"><span><i class="dot"></i><span id="storage-status" role="status">${cloud?esc(cloudLabel(cloud.status)):'Stored in this browser'}</span></span><button class="button light sm desktop-only" data-nav="myhome">My home</button>${cloud?'<button class="button light sm" data-action="signout">Sign out</button>':''}</div></header><div class="content">${loadError?`<div class="notice warning">${esc(loadError)}</div><div class="spacer"></div>`:''}${({home:homeView,checklist:checklistView,budget:budgetView,quotes:quotesView,appliances:appliancesView,receipts:receiptsView,myhome:myHomeView,guide:guideView,seller:sellerView,more:moreView}[page]||homeView)()}</div></main><nav class="mobile-nav" aria-label="Mobile navigation">${mobileNav.map(item=>navButton(item,page===item[0]||(item[0]==='more'&&['appliances','receipts','myhome','guide','seller'].includes(page)))).join('')}</nav></div>`;
}
function homeView(){
  const p=state.project,t=totals(state),pr=progress(state.tasks), used=t.target?Math.round(t.agreed/t.target*100):null;
  const active=state.tasks.filter(x=>!x.archived&&!['Done','Skip'].includes(x.status)).sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999')||stages.indexOf(a.stage)-stages.indexOf(b.stage));
  const metrics=[['Renovation target',money(t.target),'Your planned spending limit',''],['Funds available now',money(p.savings),p.savingsDate?`Savings as of ${esc(p.savingsDate)}`:'Set your current savings balance','alt'],['Agreed costs',money(t.agreed),'Prices confirmed with suppliers',''],['Already paid',money(t.paid),'Payments less refunds','']];
  const months=[]; const now=new Date(); for(let i=5;i>=0;i--){const d=new Date(now.getFullYear(),now.getMonth()-i,1);const key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`; const paid=state.payments.filter(x=>!x.voided&&x.date?.startsWith(key)).reduce((s,x)=>s+(x.type==='refund'?-x.amount:x.amount),0);months.push({label:d.toLocaleString('en',{month:'short'}),key,paid});}
  const max=Math.max(1,...months.map(x=>Math.abs(x.paid)));
  const spentPct=t.target?Math.max(0,Math.min(100,t.agreed/t.target*100)):0, resPct=t.target?Math.max(0,Math.min(100-spentPct,t.reserve/t.target*100)):0;
  return `<section class="hero"><div><div class="eyebrow">✦ &nbsp; Your home journal</div><h1>Welcome to <em>${esc(p.name)}</em></h1><p>${p.type?esc(p.type)+' · ':''}${p.location?esc(p.location)+' · ':''}Follow the progress of your space from the first idea to the final finishing touch.</p><button class="button cream" data-nav="checklist">View my checklist &nbsp; ↗</button></div><div class="hero-aside"><span class="small">YOUR RENOVATION JOURNEY</span><strong>${pr.percent===null?'—':pr.percent+'%'}</strong><span class="small">checklist complete</span></div></section>
  <section class="metrics" aria-label="Financial overview">${metrics.map(([label,value,hint,cls])=>`<div class="metric ${cls}"><div class="label">${label}</div><div class="value">${value}</div><div class="hint">${hint}</div></div>`).join('')}</section>
  <div class="grid"><div class="stack"><section class="card"><div class="card-head"><div><div class="eyebrow">Project insights</div><h2>Monthly payments</h2><p class="muted small">See how much has left your renovation fund</p></div><button class="button text" data-nav="budget">View budget ↗</button></div><div class="small muted">Net paid · last 6 months</div><div class="serif" style="font-size:29px;margin:7px 0 20px">${money(months.reduce((s,x)=>s+x.paid,0))}</div><div class="chart" aria-label="Monthly net payments">${months.map(x=>`<div class="bar-col" title="${esc(x.key)}: ${esc(money(x.paid))}"><div class="bar" style="height:${Math.max(2,Math.abs(x.paid)/max*100)}%"></div><span>${x.label}</span></div>`).join('')}</div><p class="muted small" style="margin-top:30px">${months.map(x=>`${x.label}: ${money(x.paid)}`).join(' · ')}. Refunds reduce the month’s total. Undated payments are excluded from this chart.</p><div class="chart-footer"><span>Still to pay on agreed work</span><strong>${money(t.outstanding)}</strong></div>${t.overpaid?`<p class="small muted" style="margin-top:10px">Overpaid on other items: ${money(t.overpaid)}</p>`:''}</section>
  <section class="card"><div class="card-head"><div><div class="eyebrow">Before you forget</div><h2>What comes next?</h2><p class="muted small">A few things to keep your project moving.</p></div><button class="button text" data-nav="checklist">View all ↗</button></div>${active.slice(0,3).map(x=>`<div class="next-row"><div><strong>${esc(x.title)}</strong><div class="small muted" style="margin-top:5px">${esc(x.stage)}${x.due?' · Due '+esc(x.due):''}</div></div><span class="tag ${x.importance==='Must do'?'must':''}">${esc(x.importance)}</span></div>`).join('')||'<div class="empty">You’re all caught up. Add a task to keep planning.</div>'}</section></div>
  <div class="stack"><section class="card"><div class="card-head"><div><div class="eyebrow">Project insights</div><h2>Your planned budget</h2><p class="muted small">Budget allocation, not cash you have today</p></div></div>${t.unallocated<0?`<div class="notice warning">Your agreed costs and reserve exceed your target by <strong>${money(-t.unallocated)}</strong>.</div>`:`<div class="donut-wrap"><div class="donut" style="background:conic-gradient(#315b46 0 ${spentPct}%,#c2a579 ${spentPct}% ${spentPct+resPct}%,#e8ece5 ${spentPct+resPct}% 100%)"><div class="donut-inner"><span class="small muted">Used</span><strong>${used===null?'—':used+'%'}</strong><span class="small muted">of total budget</span></div></div><div class="legend"><div class="legend-row"><i class="swatch"></i>Agreed<strong>${money(t.agreed)}</strong></div><div class="legend-row"><i class="swatch" style="background:#c2a579"></i>Reserve<strong>${money(t.reserve)}</strong></div><div class="legend-row"><i class="swatch" style="background:#e2e8df"></i>Unallocated<strong>${money(t.unallocated)}</strong></div></div></div>`}</section>
  <section class="card"><div class="card-head"><div><div class="eyebrow">Project insights</div><h2>Renovation progress</h2><p class="muted small">Every completed task brings you closer to home.</p></div><button class="button text" data-nav="checklist">Open ↗</button></div><div style="display:flex;justify-content:space-between;align-items:end;margin-bottom:12px"><span class="serif" style="font-size:27px">${pr.percent===null?'No active tasks':pr.percent+'% complete'}</span><span class="small muted">${pr.done} of ${pr.total} tasks</span></div><div class="progress-track"><div class="progress-fill" style="width:${pr.percent||0}%"></div></div><div class="spacer"></div>${stages.map(stage=>{const a=progress(state.tasks.filter(x=>x.stage===stage));return a.total?`<div class="list-row small"><span>${esc(stage)} <span class="muted">${a.done}/${a.total}</span></span><strong>${a.percent}%</strong></div>`:''}).join('')}</section>
  ${categoryCard()}</div></div>`;
}
function categoryCard(){
  const groups={}; for(const c of state.costs.filter(x=>!x.voided)){let value=categoryMode==='paid'?paidForCost(state,c.id):categoryMode==='agreed'?(c.status==='agreed'?c.amount:0):c.amount;groups[c.category]=(groups[c.category]||0)+value;}
  const rows=Object.entries(groups).filter(([,v])=>v!==0).sort((a,b)=>b[1]-a[1]);const max=Math.max(1,...rows.map(([,v])=>Math.abs(v)));
  return `<section class="card"><div class="card-head"><div><div class="eyebrow">Project insights</div><h2>Where your money goes</h2><p class="muted small">Your renovation categories at a glance</p></div></div><div class="tabs">${['agreed','estimated','paid'].map(x=>`<button data-mode="${x}" class="${categoryMode===x?'active':''}">${x[0].toUpperCase()+x.slice(1)}</button>`).join('')}</div>${rows.length?rows.map(([name,val])=>`<div class="category-row"><span>${esc(name)}</span><div class="progress-track"><div class="progress-fill" style="width:${Math.abs(val)/max*100}%"></div></div><strong>${money(val)}</strong></div>`).join(''):'<div class="empty">Your categories will appear when you add a cost.</div>'}<p class="small muted">Estimated includes agreed costs plus estimates for unagreed work.</p></section>`;
}
function checklistView(){
  const pr=progress(state.tasks);const tasks=state.tasks.filter(t=>!t.archived&&(filterStatus==='All'||t.status===filterStatus)&&`${t.title} ${t.description} ${t.room} ${t.stage}`.toLowerCase().includes(filterText.toLowerCase()));
  return `${heading('Your renovation roadmap','Renovation checklist','Your ready-made guide from planning to move-in.','<button class="button" data-action="task">＋ Add task</button>')}<div class="grid"><section class="card"><div class="card-head"><h3>Overall progress</h3><strong>${pr.percent===null?'—':pr.percent+'%'}</strong></div><div class="progress-track"><div class="progress-fill" style="width:${pr.percent||0}%"></div></div><p class="muted small" style="margin-top:12px">${pr.done} completed · ${pr.remaining} remaining</p></section><section class="card"><h3>How to use</h3><p class="muted small" style="margin-top:10px;line-height:1.6">Move a task from Not started to Doing to Done, or skip it if it doesn’t apply. You can change it at any time.</p></section></div><div class="links" style="margin-top:20px"><span class="tag must">Must do</span><span class="tag helpful">Helpful</span><span class="tag">Optional</span></div><div class="filters"><input id="task-search" placeholder="Find a task or area" aria-label="Find a task" value="${esc(filterText)}"><select id="task-filter" aria-label="Filter tasks by status">${options(['All','Not started','Doing','Done','Skip'],filterStatus)}</select></div><div class="task-grid">${tasks.map(t=>`<article class="task-card"><div style="display:flex;justify-content:space-between;gap:10px"><div><h3>${esc(t.title)}</h3><p class="small muted" style="margin-top:5px">${esc(t.stage)}${t.room?' · '+esc(t.room):''}${t.due?' · Due '+esc(t.due):''}</p></div><span class="tag">${esc(t.status)}</span></div><p class="task-desc">${esc(t.description||'Add notes to keep the details in one place.')}</p><div class="task-bottom"><span class="tag ${t.importance==='Must do'?'must':t.importance==='Helpful'?'helpful':''}">${esc(t.importance)}</span><div class="task-actions"><button class="button light sm" data-action="task-next" data-id="${esc(t.id)}">${t.status==='Done'?'↺ Reopen':t.status==='Skip'?'↺ Restore':'✓ Next step'}</button><button class="icon-button" aria-label="Edit ${esc(t.title)}" data-action="task" data-id="${esc(t.id)}">✎</button><button class="icon-button" aria-label="Archive ${esc(t.title)}" data-action="task-archive" data-id="${esc(t.id)}">×</button></div></div></article>`).join('')||'<div class="card empty">No tasks match your search.</div>'}</div>`;
}
function sortHeader(table,key,label,current){
  const active=current.key===key;
  const direction=active?current.direction:'asc';
  return `<th scope="col"${active?` aria-sort="${direction==='asc'?'ascending':'descending'}"`:''}><button class="sort-button" type="button" data-sort-table="${table}" data-sort-key="${key}" aria-label="Sort ${label} ${active&&direction==='asc'?'descending':'ascending'}">${label}<span aria-hidden="true">${active?(direction==='asc'?' ↑':' ↓'):' ↕'}</span></button></th>`;
}
function inlineCell(cost,field,value,display){
  if(inlineEdit?.id===cost.id&&inlineEdit.field===field){
    const label={name:'Item',category:'Category',phase:'Phase',room:'Area',amount:'Amount',paid:'Paid'}[field];
    let input;
    if(field==='category'){
      const choices=categories.includes(value)?categories:[...categories,value];
      input=`<select name="value" aria-label="${label} for ${esc(cost.name)}">${options(choices,value)}</select>`;
    }else if(field==='phase'){
      const choices=['0','1','2','3'];if(value&&!choices.includes(value))choices.push(value);
      input=`<select name="value" aria-label="${label} for ${esc(cost.name)}"><option value=""${selected(value,'')}>No phase</option>${choices.map(p=>`<option value="${esc(p)}"${selected(p,value)}>Phase ${esc(p)}</option>`).join('')}</select>`;
    }else{
      const numeric=field==='amount'||field==='paid';
      input=`<input name="value" type="${numeric?'number':'text'}" ${numeric?'min="0" step="0.01"':'maxlength="160"'} value="${esc(value)}" aria-label="${label} for ${esc(cost.name)}" ${field==='name'?'required':''}>`;
    }
    return `<form class="inline-form" data-inline-form="${esc(field)}" data-id="${esc(cost.id)}">${input}${field==='paid'?'<span class="inline-help">Saves a correction, not a payment. Original payments stay unchanged.</span>':''}<span class="inline-error" role="alert"></span></form>`;
  }
  return `<button type="button" class="inline-cell" data-inline-field="${esc(field)}" data-id="${esc(cost.id)}" aria-label="Edit ${esc(field==='room'?'area':field)} for ${esc(cost.name)}">${display}</button>`;
}
function updateAmount(cost,amount){
  if(cost.amount!==amount){cost.amountHistory=[...(cost.amountHistory||[]),{previous:cost.amount,amount,at:new Date().toISOString()}];cost.amount=amount;}
}
function budgetView(){
  const t=totals(state), allCosts=state.costs.filter(c=>!c.voided);
  const paidFor=c=>paidForCost(state,c.id);
  const phases=[...new Set(allCosts.map(c=>String(c.phase??'')).filter(Boolean))];
  const phaseOptions=sortRows(phases,x=>x);
  const categoryOptions=sortRows([...new Set(allCosts.map(c=>c.category).filter(Boolean))],x=>x);
  const areaOptions=sortRows([...new Set(allCosts.map(c=>c.room).filter(Boolean))],x=>x);
  let costs=allCosts.filter(c=>
    (phaseFilter==='all'||(phaseFilter==='unassigned'?String(c.phase??'')==='':String(c.phase??'')===phaseFilter)) &&
    (!categoryFilter || categoryFilter===`v:${c.category}`) &&
    (!areaFilter || (areaFilter==='unassigned'?!c.room:areaFilter===`v:${c.room}`)) &&
    (paidFilter==='all'||(paidFilter==='paid'?paidFor(c)!==0:paidFor(c)===0))
  );
  const costValue={name:c=>c.name,category:c=>c.category,phase:c=>String(c.phase??''),area:c=>c.room,amount:c=>c.amount,paid:paidFor};
  if(costValue[budgetSort.key])costs=sortRows(costs,costValue[budgetSort.key],budgetSort.direction);
  const paymentValue={date:p=>p.date,item:p=>state.costs.find(c=>c.id===p.costId)?.name||'',type:p=>p.type,reference:p=>p.reference,amount:p=>p.type==='correction'?p.amount:p.type==='refund'?-p.amount:p.amount};
  let history=[...state.payments.filter(p=>!p.voided),...(state.paymentCorrections||[]).map(c=>({...c,type:'correction',date:'',reference:`Paid total correction recorded ${c.createdAt}`}))];
  if(paymentValue[paymentSort.key])history=sortRows(history,paymentValue[paymentSort.key],paymentSort.direction);
  const costHeaders=[['name','Item'],['category','Category'],['phase','Phase'],['area','Area'],['amount','Amount'],['paid','Paid']];
  const paymentHeaders=[['date','Date'],['item','Item'],['type','Type'],['reference','Reference'],['amount','Amount']];
  return `${heading('Make every decision count','Your renovation budget','Plan costs, record payments and stay in control. Imported amounts remain estimates unless acceptance was recorded.','<div class="links"><button class="button light" data-action="payment">＋ Record payment</button><button class="button" data-action="cost">＋ Add cost</button></div>')}
  <div class="small muted">Project totals · all phases</div><div class="metrics">${[['Target',t.target],['Estimated forecast',t.forecast],['Agreed costs',t.agreed],['Still to pay',t.outstanding]].map(([label,value])=>`<div class="metric"><div class="label">${label}</div><div class="value">${money(value)}</div></div>`).join('')}</div>
  <div class="notice ${t.unallocated<0||t.forecastHeadroom<0?'warning':''}">Unallocated after agreed costs and reserve: <strong>${money(t.unallocated)}</strong> · Forecast headroom after reserve: <strong>${money(t.forecastHeadroom)}</strong>. Savings are a separate snapshot.</div>
  <div class="section-title"><h2>Costs & commitments</h2><span class="small muted">${costs.length} of ${allCosts.length} items</span></div>
  <div class="budget-controls"><label for="phase-filter">Phase</label><select id="phase-filter"><option value="all"${selected(phaseFilter,'all')}>All phases</option>${phaseOptions.map(phase=>`<option value="${esc(phase)}"${selected(phaseFilter,phase)}>Phase ${esc(phase)}</option>`).join('')}<option value="unassigned"${selected(phaseFilter,'unassigned')}>No phase</option></select><label for="category-filter">Category</label><select id="category-filter"><option value=""${selected(categoryFilter,'')}>All categories</option>${categoryOptions.map(category=>`<option value="v:${esc(category)}"${selected(categoryFilter,`v:${category}`)}>${esc(category)}</option>`).join('')}</select><label for="area-filter">Area</label><select id="area-filter"><option value=""${selected(areaFilter,'')}>All areas</option>${areaOptions.map(area=>`<option value="v:${esc(area)}"${selected(areaFilter,`v:${area}`)}>${esc(area)}</option>`).join('')}<option value="unassigned"${selected(areaFilter,'unassigned')}>No area</option></select><label for="paid-filter">Paid</label><select id="paid-filter" aria-describedby="paid-filter-help"><option value="all"${selected(paidFilter,'all')}>All payments</option><option value="paid"${selected(paidFilter,'paid')}>Paid</option><option value="not-paid"${selected(paidFilter,'not-paid')}>Not paid</option></select><button type="button" class="button light sm" data-reset-filters>Reset filters</button><span id="paid-filter-help" class="small muted">Paid includes any nonzero amount, including partial payments.</span><span class="small muted">Click a cell to edit. Changes save when selected or when you leave the field. Press Esc to cancel.</span></div>
  <section class="card table-wrap">${costs.length?`<table class="budget-table"><thead><tr>${costHeaders.map(([key,label])=>sortHeader('cost',key,label,budgetSort)).join('')}<th scope="col" class="action-column">Actions</th></tr></thead><tbody>${costs.map(c=>`<tr><td>${inlineCell(c,'name',c.name,`<strong>${esc(c.name)}</strong>`)}${c.notes?`<div class="small muted">${esc(c.notes)}</div>`:''}${c.supplier?`<div class="small muted">${esc(c.supplier)}</div>`:''}</td><td>${inlineCell(c,'category',c.category,esc(c.category))}</td><td>${inlineCell(c,'phase',String(c.phase??''),String(c.phase??'')!==''?`Phase ${esc(c.phase)}`:'<span class="muted">Not set</span>')}</td><td>${inlineCell(c,'room',c.room||'',c.room?esc(c.room):'<span class="muted">Not set</span>')}</td><td>${inlineCell(c,'amount',amountValue(c.amount),money(c.amount))}</td><td>${inlineCell(c,'paid',amountValue(paidFor(c)),money(paidFor(c)))}</td><td class="action-column"><div class="budget-actions">${c.status==='agreed'?`<button class="button light sm" data-action="payment" data-id="${esc(c.id)}">Pay</button>`:''}<button class="button light sm" data-action="cost" data-id="${esc(c.id)}">Edit</button></div></td></tr>`).join('')}</tbody><tfoot><tr class="budget-total"><th scope="row" colspan="4">Total for displayed items</th><td>${money(costs.reduce((sum,c)=>sum+c.amount,0))}</td><td>${money(costs.reduce((sum,c)=>sum+paidFor(c),0))}</td><td></td></tr></tfoot></table>`:`<div class="empty">${allCosts.length?'No costs match these filters. Choose another phase, category, area or paid status.':'No costs yet. Add an estimate or an agreed cost to get started.'}</div>`}</section>
  <div class="section-title"><h2>Payment history</h2><span class="small muted">Net paid ${money(t.paid)}</span></div><section class="card table-wrap">${history.length?`<table><thead><tr>${paymentHeaders.map(([key,label])=>sortHeader('payment',key,label,paymentSort)).join('')}</tr></thead><tbody>${history.map(p=>`<tr><td>${p.date?esc(p.date):'Date not provided'}</td><td>${esc(state.costs.find(c=>c.id===p.costId)?.name||'Unknown')}</td><td>${p.type==='correction'?'Paid total correction':p.type==='refund'?'Refund':'Payment'}</td><td>${esc(p.reference||'—')}</td><td>${p.type==='refund'?'−':''}${money(p.amount)}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">Your deposits, payments and refunds will appear here.</div>'}</section>`;
}
function quotesView(){
  return `${heading('Compare with confidence','Quotations','Keep options and important details together.','<button class="button" data-action="quote">＋ Add quotation</button>')}<div class="notice">Create a cost item in Budget first, then add competing quotations to that item. Accepting a quotation updates the linked cost once.</div><div class="spacer"></div>${state.costs.filter(c=>!c.voided).map(c=>{const quotes=state.quotes.filter(q=>q.costId===c.id);return quotes.length?`<section class="card" style="margin-bottom:15px"><div class="card-head"><div><h2>${esc(c.name)}</h2><p class="muted small">${esc(c.category)} · ${c.status==='agreed'?'Agreed':'Estimated'}</p></div><button class="button light sm" data-action="quote" data-id="${esc(c.id)}">＋ Add option</button></div><div class="task-grid">${quotes.map(q=>`<div class="task-card"><div style="display:flex;justify-content:space-between;gap:8px"><h3>${esc(q.supplier)}</h3><span class="tag">${q.accepted?'Accepted':'Option'}</span></div><div class="serif" style="font-size:24px;margin:10px 0">${money(q.amount)}</div><p class="muted small">${esc(q.details||'No scope details recorded.')}</p><div class="spacer"></div>${q.accepted?'':`<button class="button light sm" data-action="accept-quote" data-id="${esc(q.id)}">Accept quotation</button>`}</div>`).join('')}</div></section>`:''}).join('')||'<div class="card empty">No quotations yet. Add a cost item, then record your first quotation.</div>'}`;
}
function appliancesView(){
  const items=state.costs.filter(c=>!c.voided&&(c.category==='Appliances'||/water heater/i.test(c.name)));
  const research=(state.research||[]).flatMap(x=>x.topics||[]);
  return `${heading('Area by area','Appliances & selections','Your appliance budget and the product research from your workbook.')}<div class="notice">Budgeted items appear here and in Budget only once. Research notes and alternative prices are for comparison and are not added to the budget.</div><div class="section-title"><h2>Budgeted appliances</h2><span class="small muted">${items.length} items</span></div><section class="card">${items.length?items.map(c=>`<div class="list-row"><div><strong>${esc(c.name)}</strong><p class="small muted" style="margin-top:5px">${esc(c.room||'Area not set')} · ${esc(c.category)}${c.phase?' · Phase '+esc(c.phase):''}${c.notes?' · '+esc(c.notes):''}</p></div><strong>${money(c.amount)}</strong></div>`).join(''):'<div class="empty">Appliance items will appear here when added in Budget.</div>'}</section><div class="section-title"><h2>Research & options</h2><span class="small muted">From the List of Appliances sheet</span></div><div class="task-grid">${research.length?research.map(topic=>`<section class="card"><h2>${esc(topic.title)}</h2><ul class="research-list">${topic.entries.map(entry=>`<li>${esc(entry)}</li>`).join('')}</ul></section>`).join(''):'<div class="card empty">No research notes have been imported.</div>'}</div>`;
}
function receiptsView(){
  const receipts=state.receipts.slice().sort((a,b)=>(b.date||'').localeCompare(a.date||''));
  return `${heading('Keep everything together','Receipts','Save your receipts and link them to a cost or payment.','<button class="button" data-action="receipt">＋ Add receipt</button>')}<div class="notice">${cloud?"Files are included in your cloud project and JSON backup. JPEG, PNG or PDF, up to 1 MB per file; the whole project is limited to 4 MB.":"Files are stored in this browser and included in your JSON backup. JPEG, PNG or PDF, up to 1 MB per file; overall browser storage is limited."} Adding a receipt does not record a payment.</div><div class="spacer"></div><section class="card">${receipts.length?receipts.map(r=>{const cost=state.costs.find(c=>c.id===r.costId),payment=state.payments.find(p=>p.id===r.paymentId);return `<div class="list-row"><div><strong>${esc(r.title)}</strong><p class="small muted" style="margin-top:6px">${esc(r.date||'No date')} · ${esc(r.filename)} · ${Math.ceil(r.size/1024)} KB${cost?' · '+esc(cost.name):''}${payment?' · '+esc(payment.date)+' '+esc(money(payment.amount)):''}</p>${r.notes?`<p class="small muted" style="margin-top:5px">${esc(r.notes)}</p>`:''}</div><div class="links"><button class="button light sm" data-action="receipt-download" data-id="${esc(r.id)}">Download</button>${r.type.startsWith('image/')?`<button class="button light sm" data-action="receipt-preview" data-id="${esc(r.id)}">Preview</button>`:''}<button class="button light sm" data-action="receipt" data-id="${esc(r.id)}">Edit</button><button class="icon-button" aria-label="Delete ${esc(r.title)}" data-action="receipt-delete" data-id="${esc(r.id)}">×</button></div></div>`}).join(''):'<div class="empty">No receipts yet. Add a receipt to keep your records together.</div>'}</section>`;
}
function myHomeView(){const p=state.project;return `${heading('Your project details','My home','Your project information, renovation target and savings snapshot.','<button class="button" data-action="settings">✎ Edit details</button>')}<div class="grid"><section class="card"><div class="card-head"><div><div class="eyebrow">Your home</div><h2>${esc(p.name)}</h2></div></div><div class="list-row"><span class="muted">Property type</span><strong>${esc(p.type||'Not set')}</strong></div><div class="list-row"><span class="muted">Location</span><strong>${esc(p.location||'Not set')}</strong></div><div class="list-row"><span class="muted">Target move-in</span><strong>${esc(p.moveIn||'Not set')}</strong></div><div class="list-row"><span class="muted">Currency</span><strong>MYR (RM)</strong></div></section><section class="card"><div class="card-head"><div><div class="eyebrow">Plan with confidence</div><h2>Your finances</h2></div></div><div class="list-row"><span class="muted">Renovation target</span><strong>${money(p.target)}</strong></div><div class="list-row"><span class="muted">Emergency reserve</span><strong>${money(p.reserve)}</strong></div><div class="list-row"><span class="muted">Funds available now</span><strong>${money(p.savings)}</strong></div><div class="list-row"><span class="muted">Savings as of</span><strong>${esc(p.savingsDate||'Not set')}</strong></div><p class="notice" style="margin-top:16px">Your savings balance is a manually maintained snapshot. Payments do not automatically change it.</p></section></div>`;}
function guideView(){const steps=[['1','Set up your home','Add your project name, budget, reserve and current savings.','myhome','Set up my home'],['2','Make your plan','Review the starter checklist, update statuses and add your own tasks.','checklist','Open checklist'],['3','Plan your budget','Add estimated or agreed costs for the work you want to do.','budget','Open budget'],['4','Compare quotations','Add supplier options to a cost and accept your chosen quotation.','quotes','View quotations'],['5','Keep track of spending','Record payments against agreed costs. Then add your receipts for reference.','receipts','Manage receipts'],['6','Review your progress','Visit Home for your budget, payment and checklist summaries.','home','Open dashboard']];return `${heading('A simple place to begin','Your renovation guide','A step-by-step guide to using your renovation companion.')}<div class="task-grid">${steps.map(([n,title,description,destination,action])=>`<section class="card"><div class="eyebrow">Step ${n}</div><h2 style="margin:8px 0">${title}</h2><p class="muted" style="line-height:1.6;margin-bottom:18px">${description}</p><button class="button light sm" data-nav="${destination}">${action} ↗</button></section>`).join('')}</div><div class="spacer"></div><div class="notice">Checklist items are planning prompts. Confirm any approvals and requirements with the appropriate local authorities or qualified professionals.</div>`;}
function sellerView(){const codes=state.sellerCodes.slice().sort((a,b)=>a.seller.localeCompare(b.seller));return `${heading('Your useful contacts','Seller codes','Keep seller contact details and reference codes together.','<button class="button" data-action="seller-code">＋ Add seller</button>')}<div class="notice">Save a seller’s contact details, reference code and notes for your own records.</div><div class="spacer"></div><section class="card">${codes.length?codes.map(c=>`<div class="list-row"><div><strong>${esc(c.seller)}</strong>${c.contact?`<p class="small muted" style="margin-top:6px">Contact: ${esc(c.contact)}</p>`:''}${c.code?`<p style="margin-top:6px"><span class="tag">Reference: ${esc(c.code)}</span></p>`:''}${c.notes?`<p class="small muted" style="margin-top:8px">${esc(c.notes)}</p>`:''}</div><div class="links"><button class="button light sm" data-action="seller-code" data-id="${esc(c.id)}">Edit</button><button class="icon-button" aria-label="Delete ${esc(c.seller)}" data-action="seller-delete" data-id="${esc(c.id)}">×</button></div></div>`).join(''):'<div class="empty">No sellers yet. Add a contact or reference code to keep it handy.</div>'}</section>`;}
function moreView(){const archived=state.tasks.filter(t=>t.archived);return `${heading('Your project','More','Find the rest of your renovation tools.')}<div class="task-grid">${[['appliances','Appliances','Review appliances and research.'],['receipts','Receipts','Save and find your project receipts.'],['myhome','My home','Update your project and finances.'],['guide','Guide','Follow the steps to get started.'],['seller','Seller codes','Keep your seller codes handy.']].map(([id,title,description])=>`<section class="card"><h2>${title}</h2><p class="muted" style="margin:8px 0 16px">${description}</p><button class="button light sm" data-nav="${id}">Open ${title} ↗</button></section>`).join('')}</div><div class="section-title"><h2>Backup & restore</h2></div><section class="card"><p class="muted" style="margin-bottom:16px">${cloud?"Your project is stored in your signed-in cloud account. Export a backup regularly.":"Data and receipts are stored only in this browser. Export a backup regularly."}</p><div class="links">${cloud?"<button class=\"button light\" data-action=\"sync-retry\">Retry sync</button>":""}<button class="button light" data-action="export">Export backup</button><button class="button light" data-action="import">Restore backup</button></div><input type="file" id="import-file" accept="application/json,.json" hidden></section>${archived.length?`<div class="section-title"><h2>Archived tasks</h2></div><section class="card">${archived.map(t=>`<div class="list-row"><span>${esc(t.title)}</span><button class="button light sm" data-action="task-restore" data-id="${esc(t.id)}">Restore</button></div>`).join('')}</section>`:''}<div class="spacer"></div><div class="notice">${cloud?"If sync fails, retry or export a backup. For a conflict, export your changes before reloading. Activity history and collaboration are not yet available.":"This local version stores data in this browser. Export regular backups."}</div>`;}
function openDialog(title,body,submitLabel='Save'){dialogContent.innerHTML=`<form id="modal-form"><div class="dialog-head"><h2 id="dialog-title">${title}</h2><button type="button" class="close" data-action="close" aria-label="Close">×</button></div>${body}<div class="error" id="form-error" role="alert"></div><div class="form-actions"><button type="button" class="button light" data-action="close">Cancel</button><button type="submit" class="button">${submitLabel}</button></div></form>`;dialog.showModal();}
function field(label,name,value='',type='text',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function select(label,name,items,value){return `<label>${label}<select name="${name}">${options(items,value)}</select></label>`;}
function fail(msg){document.querySelector('#form-error').textContent=msg;}
function endSave(msg){if(save()){dialog.close();render();notify(cloud?'Saving to cloud…':(msg||'Saved on this device'));return true;}dialog.close();render();return false;}
function settingsForm(){const p=state.project;openDialog('My home',`<div class="form-grid">${field('Project name','name',p.name,'text','required maxlength="100"')}${field('Property type','type',p.type)}${field('Location','location',p.location)}${field('Target move-in date','moveIn',p.moveIn,'date')}${field('Renovation target (RM)','target',amountValue(p.target),'number','min="0" step="0.01" required')}${field('Emergency reserve (RM)','reserve',amountValue(p.reserve),'number','min="0" step="0.01" required')}${field('Funds available now (RM)','savings',amountValue(p.savings),'number','min="0" step="0.01" required')}${field('Savings as of','savingsDate',p.savingsDate,'date')}</div><p class="notice" style="margin-top:16px">Savings are a manually updated snapshot. Recording a payment will not reduce this number.</p>`);document.querySelector('#modal-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const target=parseMoney(f.get('target')),reserve=parseMoney(f.get('reserve')),savings=parseMoney(f.get('savings'));if([target,reserve,savings].includes(null))return fail('Enter valid amounts with no more than two decimal places.');if(reserve>target)return fail('The reserve cannot exceed the renovation target.');state.project={...p,name:String(f.get('name')).trim()||'Your renovation',type:String(f.get('type')).trim(),location:String(f.get('location')).trim(),moveIn:f.get('moveIn'),target,reserve,savings,savingsDate:f.get('savingsDate')};endSave();};}
function receiptForm(id){
  const r=state.receipts.find(x=>x.id===id),costs=state.costs.filter(c=>!c.voided),payments=state.payments.filter(p=>!p.voided);
  if(id&&!r)return;
  const costOptions=costs.map(c=>`<option value="${esc(c.id)}"${selected(c.id,r?.costId)}>${esc(c.name)}</option>`).join('');
  const payOptions=payments.map(p=>`<option value="${esc(p.id)}"${selected(p.id,r?.paymentId)}>${esc(state.costs.find(c=>c.id===p.costId)?.name||'Item')} · ${esc(p.date)} · ${esc(money(p.amount))} · ${esc(p.type)}</option>`).join('');
  openDialog(r?'Edit receipt':'Add receipt',`<div class="form-grid">${field('Receipt title','title',r?.title||'','text','required maxlength="120"')}${field('Receipt date','date',r?.date||dateLocal(),'date')}<label class="full">${r?'Replace file (optional)':'Receipt file'}<input name="receiptFile" type="file" accept="image/jpeg,image/png,application/pdf" ${r?'':'required'}></label><label>Cost item (optional)<select name="costId"><option value="">No linked cost</option>${costOptions}</select></label><label>Payment (optional)<select name="paymentId"><option value="">No linked payment</option>${payOptions}</select></label><label class="full">Notes<textarea name="notes" maxlength="500">${esc(r?.notes||'')}</textarea></label></div><p class="notice" style="margin-top:15px">JPEG, PNG or PDF, up to 1 MB. If linking a payment, select its matching cost. ${cloud?"Files are included in your cloud project and backups.":"Files stay in this browser and are included in backups."}</p>`);
  const form=document.querySelector('#modal-form');let saving=false;
  form.onsubmit=async e=>{e.preventDefault();if(saving)return;const f=new FormData(form),title=String(f.get('title')).trim(),costId=String(f.get('costId')),paymentId=String(f.get('paymentId')),file=f.get('receiptFile');if(!title)return fail('Enter a receipt title.');if(paymentId&&!payments.some(p=>p.id===paymentId&&p.costId===costId))return fail('Choose the cost that matches the selected payment.');
    let attachment=r?{filename:r.filename,type:r.type,size:r.size,data:r.data}:null;
    if(file&&file.size){if(file.size>MAX_RECEIPT_BYTES||!RECEIPT_TYPES.includes(file.type))return fail('Choose a JPEG, PNG or PDF file no larger than 1 MB.');saving=true;try{const bytes=new Uint8Array(await file.arrayBuffer());if(!fileMatchesType(file.type,bytes)){saving=false;return fail('The file contents do not match the selected file type.');}let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));attachment={filename:file.name,type:file.type,size:file.size,data:btoa(binary)};}catch{saving=false;return fail('Could not read that file. Please try again.');}}
    if(!attachment){saving=false;return fail('Choose a receipt file.');}if(!dialog.open||loadError){saving=false;return;}const record={id:r?.id||uid(),title,date:String(f.get('date')),costId,paymentId,notes:String(f.get('notes')).trim(),...attachment};if(r){const index=state.receipts.findIndex(x=>x.id===r.id);if(index<0)return;state.receipts[index]=record;}else state.receipts.push(record);endSave('Receipt saved on this device');saving=false;};
}
function sellerCodeForm(id){const code=state.sellerCodes.find(x=>x.id===id);if(id&&!code)return;openDialog(code?'Edit seller':'Add seller',`<div class="form-grid">${field('Seller name','seller',code?.seller||'','text','required maxlength="100"')}${field('Contact details','contact',code?.contact||'','text','maxlength="200"')}${field('Reference code','code',code?.code||'','text','maxlength="100"')}<label class="full">Notes<textarea name="notes" maxlength="500">${esc(code?.notes||'')}</textarea></label></div><p class="notice" style="margin-top:15px">Add contact details, a reference code, or both.</p>`);document.querySelector('#modal-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),seller=String(f.get('seller')).trim(),value=String(f.get('code')).trim(),contact=String(f.get('contact')).trim();if(!seller||(!value&&!contact))return fail('Enter a seller name and at least one contact detail or reference code.');const record={id:code?.id||uid(),seller,code:value,contact,notes:String(f.get('notes')).trim()};if(code)state.sellerCodes[state.sellerCodes.findIndex(x=>x.id===id)]=record;else state.sellerCodes.push(record);endSave();};}
function receiptDownload(id){const r=state.receipts.find(x=>x.id===id);if(!r)return;const bytes=Uint8Array.from(atob(r.data),c=>c.charCodeAt(0)),url=URL.createObjectURL(new Blob([bytes],{type:r.type})),a=document.createElement('a');a.href=url;a.download=r.filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function receiptPreview(id){const r=state.receipts.find(x=>x.id===id);if(!r||!['image/jpeg','image/png'].includes(r.type))return;openDialog('Receipt preview',`<p class="muted small" style="margin-bottom:12px">${esc(r.title)} · ${esc(r.filename)}</p><img alt="${esc(r.title)}" style="max-width:100%;max-height:60vh;object-fit:contain" src="data:${r.type};base64,${r.data}">`,'Close');document.querySelector('#modal-form').onsubmit=e=>{e.preventDefault();dialog.close();};}
function taskForm(id){const t=state.tasks.find(x=>x.id===id)||{title:'',stage:'Planning',room:'',importance:'Helpful',status:'Not started',due:'',description:''};openDialog(id?'Edit task':'Add a task',`<div class="form-grid">${field('Task','title',t.title,'text','required maxlength="160"')}${select('Stage','stage',stages,t.stage)}${field('Area (optional)','room',t.room)}${select('Importance','importance',['Must do','Helpful','Optional'],t.importance)}${select('Status','status',['Not started','Doing','Done','Skip'],t.status)}${field('Due date (optional)','due',t.due,'date')}<label class="full">Notes / why it matters<textarea name="description">${esc(t.description)}</textarea></label></div>`);document.querySelector('#modal-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const title=String(f.get('title')).trim();if(!title)return fail('Enter a task name.');Object.assign(t,{title,stage:f.get('stage'),room:String(f.get('room')).trim(),importance:f.get('importance'),status:f.get('status'),due:f.get('due'),description:String(f.get('description')).trim()});if(!id)state.tasks.push({...t,id:uid()});endSave();};}
function costForm(id){
  const c=state.costs.find(x=>x.id===id)||{name:'',category:'Construction',room:'',supplier:'',status:'estimated',amount:0,phase:''};
  const currentPhase=String(c.phase??'');
  const phases=['0','1','2','3'];
  if(currentPhase&&!phases.includes(currentPhase))phases.push(currentPhase);
  const hasPayments=state.payments.some(p=>!p.voided&&p.costId===id)||(state.paymentCorrections||[]).some(p=>p.costId===id)||state.quotes.some(q=>q.costId===id&&q.accepted);
  openDialog(id?'Edit cost':'Add a cost',`<div class="form-grid">${field('Item or work package','name',c.name,'text','required maxlength="160"')}${select('Category','category',categories,c.category)}<label>Phase<select name="phase"><option value=""${selected(currentPhase,'')}>No phase</option>${phases.map(phase=>`<option value="${esc(phase)}"${selected(currentPhase,phase)}>Phase ${esc(phase)}</option>`).join('')}</select></label>${field('Area (optional)','room',c.room)}${field('Supplier (optional)','supplier',c.supplier)}<label>Status<select name="status"><option value="estimated"${selected('estimated',c.status)}>Estimated</option><option value="agreed"${selected('agreed',c.status)}>Agreed</option></select></label>${field('Amount (RM)','amount',amountValue(c.amount),'number','min="0" step="0.01" required')}</div>${hasPayments?'<p class="notice" style="margin-top:15px">Changing the amount keeps existing payments and quotations. The previous amount is kept in this item’s history. Status cannot be changed after a payment or accepted quote.</p>':''}${c.amountHistory?.length?`<div class="notice" style="margin-top:12px"><strong>Amount history</strong>${c.amountHistory.map(h=>`<div>${esc(h.at)}: ${money(h.previous)} → ${money(h.amount)}</div>`).join('')}</div>`:''}`);
  document.querySelector('#modal-form').onsubmit=e=>{
    e.preventDefault();const f=new FormData(e.target),amount=parseMoney(f.get('amount')),name=String(f.get('name')).trim(),phase=String(f.get('phase')??'');
    if(!name||amount===null)return fail('Enter an item and a valid amount.');
    if(phase&&!phases.includes(phase))return fail('Choose a valid phase.');
    if(hasPayments&&f.get('status')!==c.status)return fail('Status cannot be changed after payments or quotation acceptance in this version.');
    if(id)updateAmount(c,amount);else c.amount=amount;
    Object.assign(c,{name,category:f.get('category'),phase,room:String(f.get('room')).trim(),supplier:String(f.get('supplier')).trim(),status:f.get('status')});
    if(!id)state.costs.push({...c,id:uid()});endSave();
  };
}
function paymentForm(costId){
  const costs=state.costs.filter(c=>!c.voided&&c.status==='agreed');if(!costs.length){alert('Add an agreed cost before recording a payment.');return;}
  const paymentOptions=state.payments.filter(p=>!p.voided&&p.type==='payment').map(p=>`<option value="${esc(p.id)}">${esc(state.costs.find(c=>c.id===p.costId)?.name||'Item')} · ${esc(p.date)} · ${esc(money(p.amount))}</option>`).join('');
  openDialog('Record a payment',`<div class="form-grid"><label>Agreed cost<select name="costId" required>${costs.map(c=>`<option value="${esc(c.id)}"${selected(c.id,costId)}>${esc(c.name)}</option>`).join('')}</select></label><label>Type<select name="type" id="payment-type"><option value="payment">Payment / deposit</option><option value="refund">Refund</option></select></label>${field('Amount (RM)','amount','','number','min="0.01" step="0.01" required')}${field('Date','date',dateLocal(),'date',`required max="${dateLocal()}"`)}${field('Method (optional)','method','')}${field('Reference (optional)','reference','')}<label id="original-label" class="full" hidden>Original payment<select name="originalId"><option value="">Select original payment</option>${paymentOptions}</select></label></div><p class="notice" style="margin-top:15px">A payment does not change your savings snapshot. Refunds are linked to the original payment.</p>`);
  const form=document.querySelector('#modal-form');form.querySelector('#payment-type').onchange=e=>{form.querySelector('#original-label').hidden=e.target.value!=='refund';};
  form.onsubmit=e=>{e.preventDefault();const f=new FormData(form),amount=parseMoney(f.get('amount')),cost=costs.find(c=>c.id===f.get('costId'));if(!cost||!amount||!f.get('date')||f.get('date')>dateLocal())return fail('Choose an agreed item, a positive amount and a date no later than today.');
    if(f.get('type')==='refund'){const original=state.payments.find(p=>p.id===f.get('originalId')&&p.costId===cost.id&&p.type==='payment'&&!p.voided);if(!original)return fail('Select an original payment for the chosen cost.');const refunded=state.payments.filter(p=>p.type==='refund'&&!p.voided&&p.originalId===original.id).reduce((s,p)=>s+p.amount,0);if(amount>original.amount-refunded)return fail('The refund exceeds the remaining amount of the original payment.');if(f.get('date')<original.date)return fail('The refund date cannot be before the original payment.');}
    else {const net=paidForCost(state,cost.id);if(net+amount>cost.amount&&!confirm(`This payment exceeds the agreed cost by ${money(net+amount-cost.amount)}. Record it anyway?`))return;const duplicate=state.payments.some(p=>!p.voided&&p.type==='payment'&&p.costId===cost.id&&p.amount===amount&&p.date===f.get('date'));if(duplicate&&!confirm('A payment with the same cost, amount and date already exists. Record another?'))return;}
    state.payments.push({id:uid(),costId:cost.id,type:f.get('type'),amount,date:f.get('date'),method:String(f.get('method')).trim(),reference:String(f.get('reference')).trim(),originalId:f.get('type')==='refund'?f.get('originalId'):''});endSave();};
}
function quoteForm(costId){const costs=state.costs.filter(c=>!c.voided);if(!costs.length){alert('Add a cost item in Budget before adding a quotation.');return;}openDialog('Add quotation',`<div class="form-grid"><label>Cost item<select name="costId">${costs.map(c=>`<option value="${esc(c.id)}"${selected(c.id,costId)}>${esc(c.name)}</option>`).join('')}</select></label>${field('Supplier','supplier','','text','required')}${field('Quoted amount (RM)','amount','','number','min="0" step="0.01" required')}${field('Quote date','date',dateLocal(),'date')}<label class="full">Scope, inclusions & exclusions<textarea name="details" placeholder="Add the details that matter when comparing options"></textarea></label></div>`);document.querySelector('#modal-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),amount=parseMoney(f.get('amount')),supplier=String(f.get('supplier')).trim();if(amount===null||!supplier)return fail('Enter a supplier and valid amount.');state.quotes.push({id:uid(),costId:f.get('costId'),supplier,amount,date:f.get('date'),details:String(f.get('details')).trim(),accepted:false});endSave();};}
function acceptQuote(id){const q=state.quotes.find(x=>x.id===id),c=state.costs.find(x=>x.id===q?.costId);if(!q||!c)return;if(state.payments.some(p=>!p.voided&&p.costId===c.id)){alert('This item has payments. Revising an agreement is not supported in this early version.');return;}if(c.status==='agreed'||state.quotes.some(x=>x.costId===c.id&&x.accepted)){alert('This item already has an agreed cost. Revisions and audit history are planned for a later release.');return;}if(!confirm(`Accept ${q.supplier}'s quotation for ${money(q.amount)}? This will replace the estimate for ${c.name}.`))return;state.quotes.filter(x=>x.costId===c.id).forEach(x=>x.accepted=false);q.accepted=true;c.amount=q.amount;c.status='agreed';c.supplier=q.supplier;commit('Quotation accepted');}
function exportBackup(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`renovation-backup-${dateLocal()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function validBackup(x){return x&&x.version===1&&x.project&&typeof x.project.name==='string'&&['target','reserve','savings'].every(k=>Number.isSafeInteger(x.project[k])&&x.project[k]>=0)&&x.project.reserve<=x.project.target&&Array.isArray(x.costs)&&Array.isArray(x.payments)&&Array.isArray(x.quotes)&&Array.isArray(x.tasks)&&x.costs.every(c=>typeof c.id==='string'&&typeof c.name==='string'&&['agreed','estimated'].includes(c.status)&&Number.isSafeInteger(c.amount)&&c.amount>=0)&&x.payments.every(p=>x.costs.some(c=>c.id===p.costId)&&['payment','refund'].includes(p.type)&&Number.isSafeInteger(p.amount)&&p.amount>0&&typeof p.date==='string')&&x.quotes.every(q=>x.costs.some(c=>c.id===q.costId)&&typeof q.supplier==='string'&&Number.isSafeInteger(q.amount)&&q.amount>=0)&&x.tasks.every(t=>typeof t.title==='string'&&typeof t.stage==='string'&&typeof t.importance==='string'&&['Not started','Doing','Done','Skip'].includes(t.status))&&validNewSections(x);}
app.addEventListener('click',e=>{const navEl=e.target.closest('[data-nav]');if(navEl){if(inlineEdit){notify('Correct the current field or press Esc to cancel.');return;}page=navEl.dataset.nav;render();window.scrollTo(0,0);return;}const mode=e.target.closest('[data-mode]');if(mode){categoryMode=mode.dataset.mode;render();return;}const el=e.target.closest('[data-action]');if(!el)return;if(inlineEdit){notify('Correct the current field or press Esc to cancel.');return;}const {action,id}=el.dataset;if(action==='settings')settingsForm();else if(action==='task')taskForm(id);else if(action==='cost')costForm(id);else if(action==='payment')paymentForm(id);else if(action==='quote')quoteForm(id);else if(action==='receipt')receiptForm(id);else if(action==='receipt-download')receiptDownload(id);else if(action==='receipt-preview')receiptPreview(id);else if(action==='receipt-delete'){const r=state.receipts.find(x=>x.id===id);if(r&&confirm(`Delete receipt “${r.title}”? This removes its local file. Existing backups are unchanged.`)){state.receipts=state.receipts.filter(x=>x.id!==id);commit('Receipt deleted');}}else if(action==='seller-code')sellerCodeForm(id);else if(action==='seller-delete'){const c=state.sellerCodes.find(x=>x.id===id);if(c&&confirm(`Delete seller “${c.seller}”?`)){state.sellerCodes=state.sellerCodes.filter(x=>x.id!==id);commit('Seller deleted');}}else if(action==='accept-quote')acceptQuote(id);else if(action==='export')exportBackup();else if(action==='import')document.querySelector('#import-file').click();else if(action==='task-next'){const t=state.tasks.find(t=>t.id===id);if(t){t.status=({'Not started':'Doing','Doing':'Done','Done':'Not started','Skip':'Not started'})[t.status];commit();}}else if(action==='task-archive'){const t=state.tasks.find(t=>t.id===id);if(t&&confirm(`Archive “${t.title}”? It will no longer count in progress.`)){t.archived=true;commit('Task archived');}}else if(action==='task-restore'){const t=state.tasks.find(t=>t.id===id);if(t){t.archived=false;commit('Task restored');}}});
dialog.addEventListener('click',e=>{if(e.target.closest('[data-action="close"]'))dialog.close();});
app.addEventListener('input',e=>{if(e.target.id==='task-search'){const start=e.target.selectionStart;filterText=e.target.value;render();const input=document.querySelector('#task-search');input.focus();input.setSelectionRange(start,start);}});
app.addEventListener('click',async e=>{
  const button=e.target.closest('[data-action]');if(!button||!cloud)return;
  if(button.dataset.action==='sync-retry'){
    if(cloud.status.state==='conflict'){alert('Your project changed on another device. Export your backup, then reload to review the conflict.');return;}
    cloud.session.retry();return;
  }
  if(button.dataset.action==='signout'){
    if(inlineEdit){notify('Finish or cancel the current edit first.');return;}
    if(cloud.session.hasDraft()){alert('Some changes are not yet synced. Retry sync or export a backup before signing out.');return;}
    try{await cloud.identity.logout();location.reload();}catch{alert('Could not sign out. Please try again.');}
  }
});
app.addEventListener('click',e=>{
  const button=e.target.closest('[data-inline-field]');if(!button)return;
  if(inlineEdit){notify('Correct the current field or press Esc to cancel.');return;}
  const field=button.dataset.inlineField,id=button.dataset.id;
  if(!['name','category','phase','room','amount','paid'].includes(field)||!state.costs.some(c=>c.id===id&&!c.voided))return;
  inlineEdit={id,field};render();
  document.querySelector('.inline-form [name="value"]')?.focus();
});
function saveInline(form,deferRender=false){
  if(!form)return false;
  const {inlineForm:field,id}=form.dataset;
  if(!inlineEdit||inlineEdit.id!==id||inlineEdit.field!==field)return false;
  const c=state.costs.find(x=>x.id===id&&!x.voided);if(!c)return false;
  const value=String(form.elements.namedItem('value').value).trim(),error=form.querySelector('.inline-error');
  if(field==='name'&&!value){error.textContent='Enter an item name.';return false;}
  if(['amount','paid'].includes(field)&&parseMoney(value)===null){error.textContent='Enter an amount with up to two decimal places.';return false;}
  if(field==='category'&&!categories.includes(value)&&value!==c.category){error.textContent='Choose a valid category.';return false;}
  if(field==='phase'&&value&&!['0','1','2','3',String(c.phase??'')].includes(value)){error.textContent='Choose a valid phase.';return false;}
  if(loadError){error.textContent=loadError;return false;}
  if(field==='amount')updateAmount(c,parseMoney(value));else if(field==='paid'){
    const difference=parseMoney(value)-paidForCost(state,c.id);
    if(difference)state.paymentCorrections.push({id:uid(),costId:c.id,amount:difference,createdAt:new Date().toISOString()});
  }else c[field]=value;
  inlineEdit=null;
  const saved=save();
  if(saved)notify(cloud?'Saving to cloud…':'Saved on this device');
  if(deferRender)setTimeout(()=>{if(page==='budget'&&!inlineEdit&&!dialog.open)render();},0);else render();
  return saved;
}
app.addEventListener('submit',e=>{const form=e.target.closest('[data-inline-form]');if(!form)return;e.preventDefault();saveInline(form);});
app.addEventListener('change',e=>{if(e.target.tagName==='SELECT'){const form=e.target.closest('[data-inline-form]');if(form)saveInline(form);}});
app.addEventListener('focusout',e=>{const form=e.target.closest('[data-inline-form]');if(form&&!form.contains(e.relatedTarget))saveInline(form,true);});
app.addEventListener('keydown',e=>{if(e.key==='Escape'&&inlineEdit&&e.target.closest('[data-inline-form]')){e.preventDefault();inlineEdit=null;render();}});
app.addEventListener('click',e=>{
  if(!e.target.closest('[data-reset-filters]'))return;
  if(inlineEdit){notify('Correct the current field or press Esc to cancel.');return;}
  phaseFilter='all';categoryFilter='';areaFilter='';paidFilter='all';
  render();document.querySelector('[data-reset-filters]')?.focus();
});
app.addEventListener('click',e=>{
  const button=e.target.closest('[data-sort-table]');
  if(!button)return;
  if(inlineEdit){notify('Correct the current field or press Esc to cancel.');return;}
  const {sortTable,sortKey}=button.dataset;
  const allowed={cost:['name','category','phase','area','amount','paid'],payment:['date','item','type','reference','amount']};
  if(!allowed[sortTable]?.includes(sortKey))return;
  const current=sortTable==='cost'?budgetSort:paymentSort;
  const next={key:sortKey,direction:current.key===sortKey&&current.direction==='asc'?'desc':'asc'};
  if(sortTable==='cost')budgetSort=next;else paymentSort=next;
  render();
  document.querySelector(`[data-sort-table="${sortTable}"][data-sort-key="${sortKey}"]`)?.focus();
});
app.addEventListener('change',e=>{const id=e.target.id;if(!['phase-filter','category-filter','area-filter','paid-filter'].includes(id))return;if(inlineEdit){notify('Correct the current field or press Esc to cancel.');e.target.value=id==='phase-filter'?phaseFilter:id==='category-filter'?categoryFilter:id==='area-filter'?areaFilter:paidFilter;return;}if(id==='phase-filter')phaseFilter=e.target.value;else if(id==='category-filter')categoryFilter=e.target.value;else if(id==='area-filter')areaFilter=e.target.value;else paidFilter=e.target.value;render();document.querySelector(`#${id}`)?.focus();});
app.addEventListener('change',async e=>{if(e.target.id==='task-filter'){filterStatus=e.target.value;render();}if(e.target.id==='import-file'&&e.target.files[0]){try{const imported=withNewSections(JSON.parse(await e.target.files[0].text()));if(!validBackup(imported))throw Error('This file is not a valid Renovation Companion backup.');if(!confirm(cloud?'Replace your signed-in cloud project with this backup? Export the current project first if you need to keep it.':'Replace the data in this browser with this backup? Export the current data first if you need to keep it.'))return;const old=state,oldError=loadError;state=imported;loadError='';if(!save()){state=old;loadError=oldError;return;}render();notify(cloud?'Backup queued for cloud sync':'Backup restored');}catch(err){alert(`Could not restore backup: ${err.message}`);}}});
window.addEventListener('storage',e=>{if(e.key===KEY){alert('This project changed in another tab. Reload this tab before making further edits.');loadError='Project changed in another tab. Reload to continue.';render();}});
